// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: NETM succeeds ONLY for the owner (the deployer of c).
        assertTrue(!ok || caller == address(this));
    }
}
